          code: "m = __import__('math')\npi = m.pi\n\ndef coeff_b(n):\n    if n % 2 == 0:\n        return 0.0\n    return 4.0 / (n * pi)\n\nx0 = pi / 2.0\nprint('n    b_n        部分和 S_n(pi/2)')\ns = 0.0\nfor n in range(1, 10):\n    s = s + coeff_b(n) * m.sin(n * x0)\n    print('%-4d %-11.6f %.6f' % (n, coeff_b(n), s))\n\nprint()\nprint('部分和在 x = pi/2 的收敛（交错级数，误差按 1/N 衰减）：')\nfor N in (1, 11, 101, 1001):\n    s = 0.0\n    for n in range(1, N + 1):\n        s = s + coeff_b(n) * m.sin(n * x0)\n    print('  N = %-5d S_N(pi/2) = %.6f  误差 = %+.6f' % (N, s, s - 1.0))\n\nprint()\nprint('吉布斯过冲：在整个周期上扫描部分和的最大值')\npts = 2000\nxs = [i * 2.0 * pi / pts for i in range(pts + 1)]\nfor N in (11, 101, 1001):\n    vals = [0.0] * (pts + 1)\n    for n in range(1, N + 1, 2):\n        b = coeff_b(n)\n        for i in range(pts + 1):\n            vals[i] = vals[i] + b * m.sin(n * xs[i])\n    best = max(vals)\n    print('  N = %-5d max = %.6f  过冲 = %.6f  占跳变量 2 的 %.3f%%' % (N, best, best - 1.0, (best - 1.0) * 50.0))\nprint('  理论极限 (2/pi) * Si(pi) = 1.178980，过冲 0.178980，占跳变量 2 的 8.949%')\n\nprint()\nprint('Parseval 检验（方波）：a0^2/2 + sum b_n^2 = (1/pi) * int f^2 dx')\ns = 0.0\nfor n in range(1, 200001, 2):\n    b = coeff_b(n)\n    s = s + b * b\nprint('  sum_{n 奇} b_n^2 = %.6f   理论值 2（因为 sum 1/n^2 = pi^2/8）' % s)\nprint('  右端 (1/pi) * int f^2 dx = (1/pi) * 2 pi = 2.000000')\nprint('  等价形式：sum_{n 奇} 1/n^2 = pi^2/8 = %.6f' % (pi * pi / 8.0))\n\nprint()\nprint('三角波对照：a_n = 8/(n^2 pi^2)，n 奇；系数按 1/n^2 衰减，级数一致收敛')\nfor n in (1, 3, 5, 7):\n    print('  n = %-3d a_n = %.6f' % (n, 8.0 / (n * n * pi * pi)))\ns2 = 0.0\nfor n in range(1, 2000001, 2):\n    a = 8.0 / (n * n * pi * pi)\n    s2 = s2 + a * a\nprint('  三角波 sum a_n^2 = %.6f   理论值 (8/pi^2)^2 * pi^4/96 = 2/3 = 0.666667' % s2)\nprint('  合并常数项核对：a0^2/2 + sum a_n^2 = 1/2 + 2/3 = 7/6 = (1/pi) * int (1-2|x|/pi)^2 dx')\n"
