          code: "m = __import__('math')\npi = m.pi\n\ndef integrate(f, a, b, n):\n    h = (b - a) / n\n    s = 0.0\n    for i in range(1, n + 1):\n        s = s + f(a + (i - 0.5) * h) * h\n    return s\n\ndef gauss(x):\n    return m.exp(-pi * x * x)\n\nprint('用矩形脉冲 phi_eps 逼近 delta：<phi_eps, gauss> 应趋于 gauss(0) = 1')\nprint('eps      内积        与 1 的差')\nfor eps in (1.0, 0.5, 0.25, 0.1, 0.01):\n    val = integrate(lambda x: gauss(x) / (2.0 * eps), -eps, eps, 200000)\n    print('%-8.2f %-11.6f %+.6f' % (eps, val, val - 1.0))\n\nprint()\nprint('phi_eps 的傅里叶变换 = sin(2 pi xi eps)/(2 pi xi eps)，eps 越小越平坦：')\nprint('xi      eps=1.0     eps=0.5     eps=0.1')\nfor xi in (0.0, 0.25, 0.5, 1.0, 2.0):\n    row = '%-7.2f' % xi\n    for eps in (1.0, 0.5, 0.1):\n        if abs(xi) < 1e-9:\n            row = row + '%-12.6f' % 1.0\n        else:\n            row = row + '%-12.6f' % (m.sin(2.0 * pi * xi * eps) / (2.0 * pi * xi * eps))\n    print(row)\nprint('结论：eps -> 0 时幅度在任意固定 xi 上都趋于 1，即 delta 的谱是常数 1')\n\nprint()\nprint('delta 的导数作用：用 phi_eps 逼近并做分部积分')\nprint('  phi = x^3 时 phi(3)(0) = 0，<delta\\', x^3> = -0 = 0')\nprint('  phi = x   时 phi(1)(0) = 1，<delta\\', x>   = -1')\nfor eps in (0.5, 0.25, 0.1):\n    # <phi_eps, x^2> = (1/(2 eps)) int_{-eps}^{eps} x^2 dx = eps^2/3 -> 0\n    val = (1.0 / (2.0 * eps)) * (2.0 * eps * eps * eps / 3.0)\n    print('  eps = %.2f : <phi_eps, x^2> = %.6f   而 <delta, x^2> = 0（普通函数积分给 eps^2/3，趋于 0 却永远不是 0）' % (eps, val))\nprint('  一阶导核对：<phi_eps\\', x^2> = -<phi_eps, 2x> = 0（奇函数积分为 0），而 <delta\\', x^2> = -2x|_0 = 0，两者一致')\nprint('  二阶导核对：<phi_eps\\',\\', x^2> = <phi_eps, 2> = 2（因为 int phi_eps = 1），与 <delta\\',\\', x^2> = 2 完全相符')\n\nprint()\nprint('跳跃函数求导含 delta 的数值示意：H(x) 的差商在 0 附近')\nfor h in (1.0, 0.5, 0.25, 0.1):\n    # (H(h/2) - H(-h/2))/h = 1/h，积分面积为 1\n    val = 1.0 / h\n    print('  步长 h = %-6.2f 差商 = %-8.2f 差商 * h = 1.0（面积守恒，正是 delta 的特征）' % (h, val))\n"
