          code: "m = __import__('math')\npi = m.pi\n\ndef integrate(f, a, b, n):\n    h = (b - a) / n\n    s = 0.0\n    for i in range(1, n + 1):\n        s = s + f(a + (i - 0.5) * h) * h\n    return s\n\ndef sigma_x_sq(a, L=20.0, n=2000000):\n    # f(x) = exp(-a x^2)，|f|^2 = exp(-2 a x^2)，用数值积分求二阶矩\n    I0 = integrate(lambda x: m.exp(-2.0 * a * x * x), -L, L, n)\n    I2 = integrate(lambda x: x * x * m.exp(-2.0 * a * x * x), -L, L, n)\n    return I2 / I0\n\nprint('高斯 f(x) = exp(-a x^2) 的不确定性乘积（酉约定，下界 1/(4 pi) = %.6f）' % (1.0 / (4.0 * pi)))\nprint('a      sigma_x^2(数值)  sigma_x^2(理论)  sigma_x    sigma_xi   乘积')\nfor a in (0.25, 0.5, 1.0, 2.0, 4.0):\n    sx2 = sigma_x_sq(a)\n    th = 1.0 / (4.0 * a)\n    sx = m.sqrt(sx2)\n    sxi = m.sqrt(a) / (2.0 * pi)\n    print('%-6.2f %-16.6f %-16.6f %-10.6f %-11.6f %.6f' % (a, sx2, th, sx, sxi, sx * sxi))\n\nprint()\nprint('对照：矩形脉冲 f = 1(|x|<1) 与指数 f = exp(-|x|) 的理论值')\nprint('  矩形： sigma_x^2 = 1/3, sigma_xi^2 = 2/3 -> 乘积 = sqrt(2)/3 = %.6f  （下界的 %.2f 倍）' % (m.sqrt(1.0 / 3.0) * m.sqrt(2.0 / 3.0), (m.sqrt(1.0 / 3.0) * m.sqrt(2.0 / 3.0)) / (1.0 / (4.0 * pi))))\nprint('  指数： sigma_x^2 = 2,   sigma_xi^2 = 1/2 -> 乘积 = 1.000000  （下界的 %.2f 倍）' % (1.0 / (1.0 / (4.0 * pi))))\n\nprint()\nprint('取等条件的数值印证：柯西-施瓦茨要求 x f(x) 与 f\\'(x) 线性相关，解得 f = C exp(-a x^2)')\nprint('  检验 a = 1：f\\'(x) = -2x f(x)，故 x f(x) = -0.5 f\\'(x)，相关系数 lambda = -0.5')\nprint('  检验 a = 4：f\\'(x) = -8x f(x)，故 x f(x) = -0.125 f\\'(x)，lambda = -1/(2a) = -0.125')\nfor a in (1.0, 4.0):\n    print('    a = %.1f : -1/(2a) = %.6f' % (a, -1.0 / (2.0 * a)))\n\nprint()\nprint('STFT 的窗与分辨率（高斯窗 g(t) = exp(-pi t^2)）：')\nsigma_t = 1.0 / m.sqrt(2.0 * pi)\nprint('  sigma_t = sigma_xi = 1/sqrt(2 pi) = %.6f' % sigma_t)\nprint('  时频格子面积 = sigma_t * sigma_xi = %.6f = 1/(2 pi)' % (sigma_t * sigma_t))\nprint('  半高全宽 FWHM = 2 sqrt(ln2/(2 pi)) = %.6f' % (2.0 * m.sqrt(m.log(2.0) / (2.0 * pi))))\n\nprint()\nprint('线性调频信号 x(t) = cos(2 pi (f0 t + (c/2) t^2))，f0 = 1 Hz, c = 2 Hz/s：')\nf0 = 1.0\nc = 2.0\nfor t in (0.0, 0.5, 1.0, 2.0):\n    print('  t = %.1f s : 瞬时频率 = %.3f Hz' % (t, f0 + c * t))\nprint('  语谱图上表现为一条斜线，斜率等于 c = %.1f Hz/s' % c)\n"
